(function(){'use strict';var SESSION_KEY='efi_session';function getSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY))||null;}catch(e){return null;}}
function renderNavAuth(){var session=getSession();var authLinks=document.querySelectorAll('.nav__auth');if(!authLinks.length)return;function clearNode(node){while(node.firstChild)node.removeChild(node.firstChild);}
function appendNavLink(container,href,label){var link=document.createElement('a');link.href=href;link.className='nav__link';link.textContent=label;container.appendChild(link);}
var page=window.location.pathname.replace(/\/+$/,'').split('/').pop().replace(/\.html$/,'');var isLearnerPage=/^(login|dashboard|curriculum|certification|certificate|verify|module-.+)$/.test(page);authLinks.forEach(function(el){clearNode(el);if(session){appendNavLink(el,'dashboard.html','Dashboard');if(session.role==='admin'||session.role==='reviewer'){appendNavLink(el,'admin.html','Admin');}}else if(isLearnerPage){appendNavLink(el,'login.html','Login');}});if(window.EFI&&typeof window.EFI.highlightActiveNavLinks==='function'){window.EFI.highlightActiveNavLinks();}}
document.addEventListener('DOMContentLoaded',renderNavAuth);})();